#define TARGET_PS2
typedef float rational_t;
typedef float sceVu0FVECTOR[4];

class quaternion
{
public:
  inline quaternion() { a=1.0f; b=c=d=0.0f; }
  inline quaternion( rational_t _a, rational_t _b, rational_t _c, rational_t _d )
    : a(_a), b(_b), c(_c), d(_d)
  {}

  rational_t a;
  rational_t b;
  rational_t c;
  rational_t d;
};

extern rational_t fast_acos(rational_t);
extern rational_t fast_sin(rational_t);

quaternion slerp( const quaternion &q0, const quaternion &q1, rational_t t )
{
#ifdef TARGET_PS2

  #if 0
    {
      static quaternion mqr;
      static quaternion mqp;

      rational_t ma, mca, ms0, ms1, misa;

      mca = q0.a * q1.a + q0.b * q1.b + q0.c * q1.c + q0.d * q1.d;
      if ( mca > 0.999999f )
      {
        mqr = q0;
      }
      else
      {
        if ( mca < 0.0f )
        {
          mca = -mca;

          if(mca > 1.0f)
            mca = 1.0f;

          mqp.a = -q1.a;
          mqp.b = -q1.b;
          mqp.c = -q1.c;
          mqp.d = -q1.d;
        }
        else
        {
          mqp.a = q1.a;
          mqp.b = q1.b;
          mqp.c = q1.c;
          mqp.d = q1.d;
        }

        ma = fast_acos( mca );
        if ( __fabs(ma) < 0.0000001f )
        {
          mqr = q0;
        }
        else
        {
          misa = 1.0f / fast_sin( ma ); 
          ms0 = fast_sin( (1.0f-t)*ma ) * misa;
          ms1 = fast_sin( t*ma ) * misa;

          mqr.a = ms0 * q0.a + ms1 * mqp.a;
          mqr.b = ms0 * q0.b + ms1 * mqp.b;
          mqr.c = ms0 * q0.c + ms1 * mqp.c;
          mqr.d = ms0 * q0.d + ms1 * mqp.d;
        }
      }
    }
  #endif

  static quaternion qr __attribute__((aligned(16)));
  static quaternion qp __attribute__((aligned(16)));
  static rational_t a, ca, s0, s1, isa;

  // If we could force the inputs to be aligned, this wouldn't be necessary...
  qr = q0;
  qp = q1;

//  rational_t a, ca, s0, s1, isa;//, sa;
  asm __volatile__(
  	"lqc2    vf9,0x0(%1) \n" // q0
	  "lqc2    vf10,0x0(%2) \n" // q1

    "vmul.xyzw vf11, vf9, vf10 \n"
	  "vaddy.x vf11, vf11, vf11 \n"
	  "vaddz.x vf11, vf11, vf11 \n"
	  "vaddw.x vf11, vf11, vf11 \n"
    "vsub.yzw vf11, vf11, vf11 \n"
	  "qmfc2   $8, vf11 \n" // dot( q0, q1 )
    "mtc1 $8, $f8 \n"

    "li.s $f9, 0.999999e0 \n"

    "c.le.s $f8, $f9 \n"
    "bc1f _exit_qslerp \n"

    "li.s $f9, 0.0e0 \n"
    "c.lt.s $f8, $f9 \n"
    "bc1f _noneg_qslerp \n"

    "li.s $f9, -1.0e0 \n"
    "c.lt.s $f8, $f9 \n"
    "bc1f _noasn_qslerp \n"
    "mov.s $f8, $f9 \n"
    "_noasn_qslerp: \n"

    "mul.s $f8, $f8, $f9 \n"

    "mfc1    $9, $f9 \n"
	  "qmtc2   $9, vf11 \n"
    "vmulx.xyzw vf10, vf10, vf11 \n"

    "_noneg_qslerp: \n"

    "mov.s %0, $f8 \n"

	: "=f" (ca) : "r" (((sceVu0FVECTOR)&qr.a)) ,"r" (((sceVu0FVECTOR)&qp.a)) : "$f8", "$f9", "$8", "$9" );

  a = fast_acos( ca );
  if ( __fabs(a) >= 0.0000001f )
  {
    isa = 1.0f / fast_sin( a ); 
    s0 = fast_sin( (1.0f-t)*a ) * isa;
    s1 = fast_sin( t*a ) * isa;

    asm __volatile__(
    	"mfc1    $8,%0 \n"
	    "qmtc2    $8,vf11 \n"
    	"vmulx.xyzw	vf13, vf9, vf11 \n"

      "mfc1    $8,%1 \n"
	    "qmtc2    $8,vf12 \n"
    	"vmulx.xyzw	vf14, vf10, vf12 \n"

      "vadd.xyzw vf9, vf13, vf14 \n"

      "sqc2 vf9, 0x0(%2) \n"

	  : :"f" (s0) ,"f" (s1), "r" (((sceVu0FVECTOR)&qr.a))  : "$8" );
  }

  // store the result
  asm __volatile__(
    "_exit_qslerp: \n"
	: : : "$8" );

/*
  if(__fabs(qr.a - mqr.a) >= 0.00001f ||
    __fabs(qr.b - mqr.b) >= 0.00001f ||
    __fabs(qr.c - mqr.c) >= 0.00001f ||
    __fabs(qr.d - mqr.d) >= 0.00001f)
  {
    printf("ps2( %f, %f, %f, %f ) =?= PC( %f, %f, %f, %f )\n", qr.a, qr.b, qr.c, qr.d, mqr.a, mqr.b, mqr.c, mqr.d);
  }
*/

  return(qr);

#else
  static quaternion qr;
  static quaternion qp;

  rational_t a, ca, s0, s1, isa;

  ca = q0.a * q1.a + q0.b * q1.b + q0.c * q1.c + q0.d * q1.d;
  if ( ca > 0.999999f )
  {
    return q0;
  }

  if ( ca < 0.0f )
  {
    ca = -ca;

    if(ca > 1.0f)
      ca = 1.0f;

    qp.a = -q1.a;
    qp.b = -q1.b;
    qp.c = -q1.c;
    qp.d = -q1.d;
  }
  else
  {
    qp.a = q1.a;
    qp.b = q1.b;
    qp.c = q1.c;
    qp.d = q1.d;
  }

  a = fast_acos( ca );
  if ( __fabs(a) < 0.0000001f )
  {
    return q0;
  }

  isa = 1.0f / fast_sin( a ); 
  s0 = fast_sin( (1.0f-t)*a ) * isa;
  s1 = fast_sin( t*a ) * isa;

  qr.a = s0 * q0.a + s1 * qp.a;
  qr.b = s0 * q0.b + s1 * qp.b;
  qr.c = s0 * q0.c + s1 * qp.c;
  qr.d = s0 * q0.d + s1 * qp.d;

  return qr;
#endif
}
